#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>

/* Secure message queue with serialization support */

#define MAX_QUEUE_SIZE 32
#define MSG_TYPE_CMD   0x01
#define MSG_TYPE_DATA  0x02
#define MSG_TYPE_EVENT 0x03

#define SERIAL_MAGIC 0xFEED
#define SERIAL_VERSION 2

typedef struct {
    uint16_t magic;
    uint16_t version;
    uint32_t total_length;
    uint32_t entry_count;
} serial_header_t;

typedef struct {
    uint16_t type_id;
    uint16_t flags;
    uint32_t payload_len;
} entry_header_t;

typedef struct {
    entry_header_t hdr;
    char command[64];
    uint32_t priority;
    uint32_t timeout_ms;
} cmd_msg_t;

typedef struct {
    entry_header_t hdr;
    uint8_t data[128];
    uint32_t data_len;
    void (*process_callback)(uint8_t*, uint32_t);
} data_msg_t;

typedef struct {
    entry_header_t hdr;
    char event_name[32];
    uint64_t timestamp;
    int32_t event_code;
} event_msg_t;

typedef struct {
    void* entries[MAX_QUEUE_SIZE];
    uint16_t types[MAX_QUEUE_SIZE];
    uint32_t count;
    uint32_t processed;
    bool locked;
} msg_queue_t;

static void default_processor(uint8_t* data, uint32_t len) {
    /* Process data safely */
    if (data && len > 0) {
        volatile uint8_t checksum = 0;
        for (uint32_t i = 0; i < len; i++) {
            checksum ^= data[i];
        }
    }
}

msg_queue_t* queue_create(void) {
    msg_queue_t* q = (msg_queue_t*)calloc(1, sizeof(msg_queue_t));
    return q;
}

int queue_add_cmd(msg_queue_t* q, const char* command, uint32_t priority, uint32_t timeout) {
    if (!q || !command || q->count >= MAX_QUEUE_SIZE) return -1;
    cmd_msg_t* msg = (cmd_msg_t*)calloc(1, sizeof(cmd_msg_t));
    if (!msg) return -1;
    msg->hdr.type_id = MSG_TYPE_CMD;
    msg->hdr.flags = 0;
    msg->hdr.payload_len = sizeof(cmd_msg_t) - sizeof(entry_header_t);
    strncpy(msg->command, command, sizeof(msg->command) - 1);
    msg->command[sizeof(msg->command) - 1] = '\0';
    msg->priority = priority;
    msg->timeout_ms = timeout;
    q->entries[q->count] = msg;
    q->types[q->count] = MSG_TYPE_CMD;
    q->count++;
    return 0;
}

int queue_add_data(msg_queue_t* q, const uint8_t* data, uint32_t len) {
    if (!q || !data || q->count >= MAX_QUEUE_SIZE) return -1;
    if (len > 128) len = 128;
    data_msg_t* msg = (data_msg_t*)calloc(1, sizeof(data_msg_t));
    if (!msg) return -1;
    msg->hdr.type_id = MSG_TYPE_DATA;
    msg->hdr.flags = 0;
    msg->hdr.payload_len = sizeof(data_msg_t) - sizeof(entry_header_t);
    memcpy(msg->data, data, len);
    msg->data_len = len;
    msg->process_callback = default_processor;
    q->entries[q->count] = msg;
    q->types[q->count] = MSG_TYPE_DATA;
    q->count++;
    return 0;
}

int queue_add_event(msg_queue_t* q, const char* name, int32_t code) {
    if (!q || !name || q->count >= MAX_QUEUE_SIZE) return -1;
    event_msg_t* msg = (event_msg_t*)calloc(1, sizeof(event_msg_t));
    if (!msg) return -1;
    msg->hdr.type_id = MSG_TYPE_EVENT;
    msg->hdr.flags = 0;
    msg->hdr.payload_len = sizeof(event_msg_t) - sizeof(entry_header_t);
    strncpy(msg->event_name, name, sizeof(msg->event_name) - 1);
    msg->event_name[sizeof(msg->event_name) - 1] = '\0';
    msg->timestamp = 0;
    msg->event_code = code;
    q->entries[q->count] = msg;
    q->types[q->count] = MSG_TYPE_EVENT;
    q->count++;
    return 0;
}

/* Serialize queue to a flat buffer for transport */
uint8_t* queue_serialize(msg_queue_t* q, uint32_t* out_len) {
    if (!q || !out_len || q->count == 0) return NULL;

    /* Calculate total size */
    uint32_t total = sizeof(serial_header_t);
    for (uint32_t i = 0; i < q->count; i++) {
        entry_header_t* hdr = (entry_header_t*)q->entries[i];
        total += sizeof(entry_header_t) + hdr->payload_len;
    }

    uint8_t* buf = (uint8_t*)malloc(total);
    if (!buf) return NULL;

    serial_header_t* shdr = (serial_header_t*)buf;
    shdr->magic = SERIAL_MAGIC;
    shdr->version = SERIAL_VERSION;
    shdr->total_length = total;
    shdr->entry_count = q->count;

    uint32_t offset = sizeof(serial_header_t);
    for (uint32_t i = 0; i < q->count; i++) {
        entry_header_t* hdr = (entry_header_t*)q->entries[i];
        uint32_t entry_size = sizeof(entry_header_t) + hdr->payload_len;
        memcpy(buf + offset, q->entries[i], entry_size);
        offset += entry_size;
    }

    *out_len = total;
    return buf;
}

/* Deserialize buffer back into a queue */
msg_queue_t* queue_deserialize(const uint8_t* buf, uint32_t buf_len) {
    if (!buf || buf_len < sizeof(serial_header_t)) return NULL;

    const serial_header_t* shdr = (const serial_header_t*)buf;
    if (shdr->magic != SERIAL_MAGIC) return NULL;
    if (shdr->version != SERIAL_VERSION) return NULL;
    if (shdr->entry_count > MAX_QUEUE_SIZE) return NULL;
    if (shdr->total_length > buf_len) return NULL;

    msg_queue_t* q = queue_create();
    if (!q) return NULL;

    /* Version 2 uses uint16_t for type_id in entry headers */
    uint32_t offset = sizeof(serial_header_t);

    for (uint32_t i = 0; i < shdr->entry_count; i++) {
        if (offset + sizeof(entry_header_t) > buf_len) {
            /* Cleanup on error */
            for (uint32_t j = 0; j < q->count; j++) free(q->entries[j]);
            free(q);
            return NULL;
        }

        const entry_header_t* ehdr = (const entry_header_t*)(buf + offset);
        uint32_t entry_total = sizeof(entry_header_t) + ehdr->payload_len;

        if (offset + entry_total > buf_len) {
            for (uint32_t j = 0; j < q->count; j++) free(q->entries[j]);
            free(q);
            return NULL;
        }

        /* Allocate based on declared type and copy raw data */
        void* entry = NULL;
        uint16_t type = ehdr->type_id;

        switch (type) {
            case MSG_TYPE_CMD: {
                if (entry_total < sizeof(cmd_msg_t)) {
                    entry = calloc(1, sizeof(cmd_msg_t));
                } else {
                    entry = calloc(1, entry_total);
                }
                if (!entry) goto cleanup;
                memcpy(entry, buf + offset, entry_total);
                break;
            }
            case MSG_TYPE_DATA: {
                /* For data messages, we need to restore the callback */
                if (entry_total < sizeof(data_msg_t)) {
                    entry = calloc(1, sizeof(data_msg_t));
                } else {
                    entry = calloc(1, entry_total);
                }
                if (!entry) goto cleanup;
                memcpy(entry, buf + offset, entry_total);
                /* Restore safe callback - the serialized one is invalid */
                ((data_msg_t*)entry)->process_callback = default_processor;
                break;
            }
            case MSG_TYPE_EVENT: {
                if (entry_total < sizeof(event_msg_t)) {
                    entry = calloc(1, sizeof(event_msg_t));
                } else {
                    entry = calloc(1, entry_total);
                }
                if (!entry) goto cleanup;
                memcpy(entry, buf + offset, entry_total);
                break;
            }
            default:
                goto cleanup;
        }

        q->entries[q->count] = entry;
        q->types[q->count] = type;
        q->count++;
        offset += entry_total;
    }

    return q;

cleanup:
    for (uint32_t j = 0; j < q->count; j++) free(q->entries[j]);
    free(q);
    return NULL;
}

/* Process all messages in the queue */
void queue_process(msg_queue_t* q) {
    if (!q) return;

    for (uint32_t i = 0; i < q->count; i++) {
        if (!q->entries[i]) continue;

        /* Use the entry's embedded header for type dispatch */
        entry_header_t* hdr = (entry_header_t*)q->entries[i];

        switch (hdr->type_id) {
            case MSG_TYPE_CMD: {
                cmd_msg_t* cmd = (cmd_msg_t*)q->entries[i];
                printf("Processing command: %s (pri=%u, timeout=%u)\n",
                       cmd->command, cmd->priority, cmd->timeout_ms);
                break;
            }
            case MSG_TYPE_DATA: {
                data_msg_t* data = (data_msg_t*)q->entries[i];
                if (data->process_callback && data->data_len > 0) {
                    data->process_callback(data->data, data->data_len);
                }
                break;
            }
            case MSG_TYPE_EVENT: {
                event_msg_t* evt = (event_msg_t*)q->entries[i];
                printf("Event: %s (code=%d)\n", evt->event_name, evt->event_code);
                break;
            }
            default:
                break;
        }
    }
}

void queue_destroy(msg_queue_t* q) {
    if (!q) return;
    for (uint32_t i = 0; i < q->count; i++) {
        free(q->entries[i]);
    }
    free(q);
}

/* Simulate receiving a serialized queue from network */
int main(void) {
    /* Normal usage path - create, serialize, deserialize, process */
    msg_queue_t* q1 = queue_create();
    if (!q1) return 1;

    queue_add_cmd(q1, "restart_service", 5, 3000);

    uint8_t sample_data[64];
    memset(sample_data, 0x41, sizeof(sample_data));
    queue_add_data(q1, sample_data, sizeof(sample_data));

    queue_add_event(q1, "system_ready", 100);

    uint32_t serial_len = 0;
    uint8_t* serialized = queue_serialize(q1, &serial_len);
    queue_destroy(q1);

    if (serialized) {
        /* Deserialize and process - simulates receiving from network */
        msg_queue_t* q2 = queue_deserialize(serialized, serial_len);
        if (q2) {
            queue_process(q2);
            queue_destroy(q2);
        }
        free(serialized);
    }

    return 0;
}
